import{at as e,it as t,n,vt as r}from"./chunks/framework.DdRMjwGS.js";var i=JSON.parse(`{"title":"访问策略与权限条件","description":"","frontmatter":{},"headers":[],"relativePath":"backend/access-policy.md","filePath":"backend/access-policy.md","lastUpdated":1794475115000}`),a={name:`backend/access-policy.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="访问策略与权限条件" tabindex="-1">访问策略与权限条件 <a class="header-anchor" href="#访问策略与权限条件" aria-label="Permalink to “访问策略与权限条件”">​</a></h1><p>本页说明访问策略、登录失败自动封禁与权限条件的规则、操作与命中记录，适用于后端开发者与安全配置人员。</p><p>两套 ABAC 能力都在 Access 包，共用框架的条件引擎（<code>Security.Abstractions.Conditions</code>：十五个运算符，IP 集合可写 CIDR，时段可以跨零点）与同一份属性目录（<code>AccessConditionAttributes</code>）：</p><table tabindex="0"><thead><tr><th></th><th>访问策略</th><th>权限条件</th></tr></thead><tbody><tr><td>作用</td><td>判定一次调用能否进入，与持有的权限无关</td><td>判定持有的某个权限码在什么条件下生效</td></tr><tr><td>挂在哪里</td><td>平台层 / 租户层的独立策略</td><td>某个授权绑定（角色或用户在某个权限码上的授予或拒绝）</td></tr><tr><td>管道位置</td><td><code>AccessPolicyMiddleware</code>，Tenant 阶段（认证与租户都已知）</td><td><code>PermissionConditionMiddleware</code>，Authorize 阶段，框架授权之后</td></tr><tr><td>拒绝时</td><td><code>ACCESS_DENIED_004</code>（403）；登录时 <code>ACCESS_DENIED_005</code></td><td><code>ACCESS_DENIED_003</code>（403），或按模式只记录</td></tr><tr><td>开关</td><td><code>BasicApp:Access:AccessPolicyEnabled</code>（缺省 <code>true</code>）</td><td><code>BasicApp:Access:PermissionConditionMode</code>（缺省 <code>Enforce</code>）</td></tr></tbody></table><p>配置见<a href="./../configuration#basicapp-access">配置参考</a>。</p><h2 id="条件属性" tabindex="-1">条件属性 <a class="header-anchor" href="#条件属性" aria-label="Permalink to “条件属性”">​</a></h2><p>属性名不区分大小写。</p><table tabindex="0"><thead><tr><th>前缀</th><th>属性</th></tr></thead><tbody><tr><td><code>subject.</code></td><td><code>userId</code>、<code>userName</code>、<code>tenantCode</code>（平台为 <code>platform</code>）、<code>roleCodes</code>、<code>departmentCodes</code>、<code>mainDepartmentCode</code>、<code>positionCodes</code>、<code>isImpersonating</code></td></tr><tr><td><code>resource.</code></td><td><code>operation</code>（操作 ID）、<code>permissionCodes</code>（本次调用要求的权限码）、<code>path</code>、<code>method</code></td></tr><tr><td><code>environment.</code></td><td><code>ip</code>、<code>geo.country</code> / <code>geo.province</code> / <code>geo.city</code> / <code>geo.isp</code>（IP 归属地）、<code>client.userAgent</code>、<code>client.kind</code>（未登录为 <code>anonymous</code>，否则为调用协议）、<code>date</code>、<code>time</code>、<code>hour</code>、<code>weekday</code>（周一为 1）</td></tr></tbody></table><ul><li>部门与岗位类属性只在租户侧有值。</li><li>日期、时刻、小时与星期按 <code>BasicApp:Access:ConditionTimeZone</code>（缺省 <code>Asia/Shanghai</code>）判定。</li><li><code>policies.attributes</code> 与 <code>permission-conditions.attributes</code> 返回同一份目录，带每个属性可用的运算符与认证前能否取得。</li></ul><div class="warning custom-block"><p class="custom-block-title">IP 类条件与反向代理</p><p>放在反向代理后时，要把代理的地址或网段写进 <code>BasicApp:ForwardedHeaders</code>（见<a href="./../configuration#basicapp-forwardedheaders">配置参考</a>），<code>environment.ip</code> 与归属地才是客户端的。</p></div><h2 id="访问策略" tabindex="-1">访问策略 <a class="header-anchor" href="#访问策略" aria-label="Permalink to “访问策略”">​</a></h2><h3 id="求值规则" tabindex="-1">求值规则 <a class="header-anchor" href="#求值规则" aria-label="Permalink to “求值规则”">​</a></h3><ul><li>平台层作用于全部外部调用（含租户的调用）；租户层只作用于已登录的本租户调用。平台层拦下即不看租户层。</li><li>只管外部协议（HTTP、gRPC、MCP）。作业、消息处理、工作流与命令行不求值，也不记命中；没有来源的内部调用（如 AI 工具）在已经求值过的外部调用之内。</li><li>层内逐条求值此刻有效的策略：有放行命中即不拒绝，否则第一条命中的拒绝策略拦下。求值顺序按优先级（越小越先）、再按编码。</li><li>动作：<code>Deny</code> 拒绝、<code>Allow</code> 放行、<code>LogOnly</code> 只记录；状态 <code>Active</code> / <code>Disabled</code>；可设生效与失效时间。</li><li>判定本身出错时放行并记警告。</li><li>登录时机：各种登录方式开会话之前、<code>auth.switch-tenant</code> 之前，由登录守卫按要进入的一侧与账号此刻的角色再求一次平台层与目标租户层，拦下即不签发令牌（<code>ACCESS_DENIED_005</code>）。</li><li>命中记录里的时机：平台策略只引用认证前就取得到的属性（地址、归属地、时间、User-Agent、路径与方法）记为「认证前」，否则「认证后」；登录守卫的命中记为「登录时」。</li><li>启用的策略按侧缓存 60 秒，写入在提交之后失效。</li></ul><p>策略把自己锁在外面时，由运维把 <code>BasicApp:Access:AccessPolicyEnabled</code> 设为 <code>false</code> 后重启。</p><h3 id="写入规则" tabindex="-1">写入规则 <a class="header-anchor" href="#写入规则" aria-label="Permalink to “写入规则”">​</a></h3><ul><li>编码在本侧唯一、不含空白；条件 1 到 100 条、至多 20 个组：组内 AND、组间 OR。</li><li>新建（含从模板新建）一律是只记录、启用；改动作与启停只经 <code>policies.set-action</code> / <code>policies.set-status</code>。</li><li>防自锁：改动之后仍是启用中、此刻有效的拒绝策略，且按发起这次修改的请求求值会命中时，拒绝保存（<code>ACCESS_VALIDATION_041</code>）。</li></ul><h3 id="操作" tabindex="-1">操作 <a class="header-anchor" href="#操作" aria-label="Permalink to “操作”">​</a></h3><table tabindex="0"><thead><tr><th>操作</th><th>权限码</th><th>说明</th></tr></thead><tbody><tr><td><code>policies.list</code> / <code>get</code> / <code>templates</code> / <code>attributes</code></td><td><code>access.policies.read</code></td><td>列表缺省按求值顺序</td></tr><tr><td><code>policies.create</code> / <code>update</code></td><td><code>access.policies.create</code> / <code>update</code></td><td></td></tr><tr><td><code>policies.set-action</code> / <code>set-status</code></td><td><code>access.policies.update</code></td><td>单条</td></tr><tr><td><code>policies.delete</code></td><td><code>access.policies.delete</code></td><td>批量，逐项结果</td></tr><tr><td><code>policies.trial</code></td><td><code>access.policies.trial</code></td><td>已有策略或草稿条件按模拟的请求属性只求这一条、不看有效期，逐组逐条件说明</td></tr></tbody></table><p>权限码两侧都有，写操作进操作日志。页面 <code>access.policies</code>（<code>/access/policies</code>）。</p><h3 id="六个模板" tabindex="-1">六个模板 <a class="header-anchor" href="#六个模板" aria-label="Permalink to “六个模板”">​</a></h3><table tabindex="0"><thead><tr><th>模板</th><th>用途</th><th>种子写入时</th></tr></thead><tbody><tr><td><code>preset.ip-blacklist</code></td><td>IP 黑名单（初始值是文档保留网段，要替换）</td><td>拒绝、停用</td></tr><tr><td><code>preset.admin-office-network</code></td><td>角色 <code>admin</code> 只能从办公网络调用</td><td>拒绝、停用</td></tr><tr><td><code>preset.sensitive-ops-network</code></td><td>导出、删除、模仿、授权等敏感操作只能从办公网络调用</td><td>拒绝、停用</td></tr><tr><td><code>preset.off-hours</code></td><td>周末与工作日 08:00–20:00 之外的访问</td><td>只记录、启用</td></tr><tr><td><code>preset.overseas</code></td><td>归属地已知且不是中国的访问</td><td>只记录、启用</td></tr><tr><td><code>preset.block-scripts</code></td><td>没有 User-Agent 或是常见脚本与爬虫的（<code>curl</code>、<code>python-requests</code>、<code>Go-http-client</code>、<code>Wget</code>、<code>Scrapy</code>、<code>HttpClient</code>），开放平台的签名调用除外</td><td>只记录、启用</td></tr></tbody></table><p>办公网段的占位值是 <code>203.0.113.0/24</code>。种子 <code>access.policies</code> 按模板在平台层补写还没有的编码，已有的不动。启用拒绝类之前替换网段，并先试运行。演示数据打开时，种子 <code>access.demo-policies</code> 在演示租户 <code>demo</code> 写两条只记录的策略（<code>demo.off-hours</code>、<code>demo.overseas</code>）。</p><h3 id="登录失败自动封禁" tabindex="-1">登录失败自动封禁 <a class="header-anchor" href="#登录失败自动封禁" aria-label="Permalink to “登录失败自动封禁”">​</a></h3><p>系统参数 <code>access.security.login-auto-ban</code>（JSON，种子建好的内建参数，缺省关闭；写错即 <code>ACCESS_VALIDATION_043</code>，不计数）：</p><table tabindex="0"><thead><tr><th>字段</th><th>缺省</th><th>范围</th></tr></thead><tbody><tr><td><code>isEnabled</code></td><td><code>false</code></td><td></td></tr><tr><td><code>windowMinutes</code></td><td><code>10</code></td><td>1–1440，固定计数窗口</td></tr><tr><td><code>maxFailures</code></td><td><code>20</code></td><td>1–10000，同一地址跨账号的失败上限</td></tr><tr><td><code>banMinutes</code></td><td><code>30</code></td><td>1–43200，首次封禁时长</td></tr><tr><td><code>maxBanMinutes</code></td><td><code>1440</code></td><td>不小于 <code>banMinutes</code>，至多 43200</td></tr></tbody></table><ul><li>认证失败（密码、两步验证、验证码登录）按调用来源地址计数，达到上限即封禁；24 小时内再犯，时长翻倍到上限。这次调用命中了平台层的放行策略时不计。</li><li>封禁中的地址在访问策略之前即被拒绝：503 <code>ACCESS_UNAVAILABLE_001</code>，带重试秒数，并记一条编码 <code>login-auto-ban</code> 的命中。<code>AccessPolicyEnabled</code> 为 <code>false</code> 时封禁照常生效。</li><li>计数与封禁在共享缓存里，只当减速手段，不当安全边界。</li></ul><table tabindex="0"><thead><tr><th>操作</th><th>权限码</th><th>说明</th></tr></thead><tbody><tr><td><code>login-bans.list</code></td><td><code>access.login-bans.read</code></td><td>此刻生效的参数与当前封禁</td></tr><tr><td><code>login-bans.lift</code></td><td><code>access.login-bans.lift</code></td><td>提前解封并清掉该地址的计数；没封着即 <code>ACCESS_NOTFOUND_009</code></td></tr></tbody></table><p>两个权限码只在平台一侧。</p><h2 id="权限条件" tabindex="-1">权限条件 <a class="header-anchor" href="#权限条件" aria-label="Permalink to “权限条件”">​</a></h2><h3 id="结构与语义" tabindex="-1">结构与语义 <a class="header-anchor" href="#结构与语义" aria-label="Permalink to “结构与语义”">​</a></h3><p>条件存在 <code>SysPermissionCondition</code>，挂在一个授权绑定（侧 × 角色或用户 × 权限码 × 授予或拒绝）上：</p><ul><li>挂在授予上是「满足才授予」，挂在拒绝上是「满足才拒绝」。</li><li>同组的子句 AND、组间 OR；每个绑定至多 5 组、每组至多 10 条，条件值至多 2000 个字符；停用的子句不参与判定。</li><li>绑定没了（撤销、授予与拒绝互换、删除角色）即连同删除。</li></ul><p>框架的权限过滤器拿不到请求属性，所以分两步：</p><ol><li>授予判定是乐观的：有条件的授予算持有，有条件的拒绝不拿走；</li><li><code>PermissionConditionMiddleware</code> 在框架授权之后，按调用来源（地址、User-Agent、路径与方法）、主体与时刻，只对操作声明的那个权限码精确判定。</li></ol><p>授予存储读不到时这次调用以 503 结束，不当作没有条件放行。</p><h3 id="模式" tabindex="-1">模式 <a class="header-anchor" href="#模式" aria-label="Permalink to “模式”">​</a></h3><p><code>BasicApp:Access:PermissionConditionMode</code>：</p><table tabindex="0"><thead><tr><th>值</th><th>不满足时</th></tr></thead><tbody><tr><td><code>Enforce</code>（缺省）</td><td>拒绝（<code>ACCESS_DENIED_003</code>），记命中</td></tr><tr><td><code>LogOnly</code></td><td>放行，记命中</td></tr><tr><td><code>Disabled</code></td><td>不判定：有条件的授予即授予、有条件的拒绝即拒绝，不记命中</td></tr></tbody></table><h3 id="操作-1" tabindex="-1">操作 <a class="header-anchor" href="#操作-1" aria-label="Permalink to “操作”">​</a></h3><table tabindex="0"><thead><tr><th>操作</th><th>权限码</th><th>说明</th></tr></thead><tbody><tr><td><code>permission-conditions.list</code> / <code>attributes</code></td><td><code>access.permission-conditions.read</code></td><td>列表按主体（<code>subjectKind</code>、<code>subjectId</code>）取，含停用的子句</td></tr><tr><td><code>permission-conditions.create</code> / <code>update</code> / <code>delete</code></td><td><code>access.permission-conditions.create</code> / <code>update</code> / <code>delete</code></td><td>删除为批量；写入记权限变更日志（<code>ConditionChange</code>）</td></tr><tr><td><code>permission-conditions.trial</code></td><td><code>access.permission-conditions.trial</code></td><td>按模拟的时间、地址等试算某人在某权限码上的结论，逐组逐子句说明</td></tr><tr><td><code>permission-conditions.batch-trial</code></td><td><code>access.permission-conditions.trial</code></td><td>影响试算：一个绑定影响到的人（角色含下级角色的成员，至多 200 人）各自的结论</td></tr><tr><td><code>permission-conditions.inventory</code></td><td><code>access.permission-conditions.trial</code></td><td>盘点：本侧每条子句的诊断（属性未登记、旧写法、编译不过、绑定已不在）</td></tr></tbody></table><p>权限码两侧都有。条件在角色页与用户页的授权抽屉里维护，试算与盘点在权限目录页。</p><h2 id="条件命中记录" tabindex="-1">条件命中记录 <a class="header-anchor" href="#条件命中记录" aria-label="Permalink to “条件命中记录”">​</a></h2><p>两套能力的命中都写进 Auditing 的条件命中日志（<code>SysConditionHit</code>，按月分表），同一规则对同一来源一分钟内的命中合并成一行（<code>hitCount</code>）：</p><ul><li>访问策略记全部命中（拒绝、放行、只记录），只有与拦截策略同层的拒绝标为拦截；平台层的命中落在平台一侧。</li><li>权限条件只记不满足的那次，<code>Enforce</code> 记为拒绝并拦截，<code>LogOnly</code> 记为只记录。</li></ul><table tabindex="0"><thead><tr><th>操作</th><th>权限码</th><th>说明</th></tr></thead><tbody><tr><td><code>condition-hits.list</code> / <code>get</code></td><td><code>auditing.condition-hits.read</code></td><td>只看当前一侧：来源、策略或权限码、动作、时机、是否拦截、操作、路径、地址与 User-Agent</td></tr></tbody></table><p>页面 <code>auditing.condition-hits</code>（<code>/auditing/condition-hits</code>）。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="./permission">权限管理</a> · <a href="./approval">约束规则与审批</a> · <a href="./logging">日志审计</a></li></ul>`,48)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};